# PersonaMem official runner, executed fully locally at $0.
#
# Why this wrapper exists
#   upstream inference.py hardcodes cloud model ids ("gpt-4o", gemini, claude,
#   lambda) and constructs `OpenAI(api_key=...)` without a base_url.  The OpenAI
#   python client honours the OPENAI_BASE_URL environment variable, so pointing it
#   at Ollama's OpenAI-compatible endpoint keeps the *upstream code untouched*
#   while every token is generated by the local qwen2.5-coder:7b weights, which
#   are published locally under the alias "gpt-4o" (created with
#   `POST /api/create {"model":"gpt-4o","from":"qwen2.5-coder:7b",...}`).
#
#   No external network request is made; the api key file only satisfies the
#   upstream `openai_key.txt` file read and is never sent anywhere but localhost.
#
# Usage:
#   pwsh -NoProfile -File scripts/benchmarks/run_personamem_local.ps1 -Scale 32K
#   pwsh -NoProfile -File scripts/benchmarks/run_personamem_local.ps1 -Scale 32K -QuestionsCsv <csv> -ResultCsv <csv>

[CmdletBinding()]
param(
    [ValidateSet("32K", "128K", "1M", "custom")]
    [string]$Scale = "32K",
    [string]$QuestionsCsv = "",
    [string]$ResultCsv = "",
    [string]$Model = "gpt-4o",
    [string]$ResultDir = ""
)

$ErrorActionPreference = "Continue"
$env:PYTHONUNBUFFERED = "1"
$env:OPENAI_BASE_URL = "http://localhost:11434/v1"
$env:OPENAI_API_KEY = "ollama-local"
$env:OPENAI_LOG = "error"

$root = (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path
$python = Join-Path $root ".venv-benchmarks\personamem\Scripts\python.exe"
$tokenPath = Join-Path $root "benchmark_results\official\personamem_lab\api_tokens"
if (-not $ResultDir) { $ResultDir = Join-Path $root "benchmark_results\official\personamem_lab" }

if ($Scale -eq "custom") {
    if (-not $QuestionsCsv -or -not $ResultCsv) {
        throw "-Scale custom requires -QuestionsCsv and -ResultCsv"
    }
    $questionPath = $QuestionsCsv
    $contextPath = Join-Path $root "datasets\official\personamem\shared_contexts_32k.jsonl"
    $resultPath = $ResultCsv
} else {
    $questionPath = Join-Path $root "datasets\official\personamem\questions_$Scale.csv"
    $contextPath = Join-Path $root "datasets\official\personamem\shared_contexts_$Scale.jsonl"
    $resultPath = Join-Path $ResultDir "personamem_$($Scale.ToLower())_results.csv"
}

New-Item -ItemType Directory -Force -Path $tokenPath | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $resultPath) | Out-Null
if (-not (Test-Path (Join-Path $tokenPath "openai_key.txt"))) {
    Set-Content -Path (Join-Path $tokenPath "openai_key.txt") -Value "ollama-local" -NoNewline
}

Write-Output "PersonaMem local run"
Write-Output "  scale      : $Scale"
Write-Output "  reader     : $Model  (local Ollama alias of qwen2.5-coder:7b, num_ctx 8192)"
Write-Output "  base_url   : $env:OPENAI_BASE_URL"
Write-Output "  questions  : $questionPath"
Write-Output "  contexts   : $contextPath"
Write-Output "  results    : $resultPath"

Push-Location (Join-Path $root "third_party\benchmarks\personamem")
try {
    & $python inference.py --step evaluate --model $Model --token_path $tokenPath `
        --question_path $questionPath --context_path $contextPath --result_path $resultPath
    Write-Output "EXIT=$LASTEXITCODE"
} finally {
    Pop-Location
}
